use std::time::Duration;
use thiserror::Error;

#[derive(Error, Debug)]
pub enum PingError {
    #[error("Error spawning ping: {0}")]
    SpawnError(#[from] std::io::Error),
    #[error("Parse error")]
    ParseError,
}

#[derive(Debug)]
pub enum PingResult {
    Pong(Duration, String),
    Timeout(String),
    PingExited(Option<i32>),
    Unknown(String),
}

pub trait Pinger: Send + Sync {
    fn start<F>(&self, target: String) -> Result<Box<dyn Iterator<Item = PingResult> + Send>, PingError>
    where
        Self: Sized;
}

pub mod linux;
pub mod macos;
pub mod windows;

use std::process::{Child, ChildStdout, Command, Stdio};
use std::io::{BufRead, BufReader, Lines};

pub struct PingIter {
    child: Child,
    lines: Lines<BufReader<ChildStdout>>,
    parser: Box<dyn Fn(&str) -> PingResult + Send>,
}

impl Iterator for PingIter {
    type Item = PingResult;

    fn next(&mut self) -> Option<Self::Item> {
        loop {
            match self.lines.next() {
                Some(Ok(line)) => {
                    let result = (self.parser)(&line);
                    match result {
                        PingResult::Unknown(_) => continue,
                        other => return Some(other),
                    }
                }
                Some(Err(_)) => return None,
                None => {
                    let exit = self.child.wait().ok().and_then(|s| s.code());
                    return Some(PingResult::PingExited(exit));
                }
            }
        }
    }
}

