cat > pinger/src/linux.rs << 'EOF'
use crate::{PingError, PingIter, PingResult};
use regex::Regex;
use std::process::{Command, Stdio};
use std::io::BufReader;
use std::time::Duration;

fn parse_ping_line(line: &str) -> PingResult {
    // Linux ping output: 64 bytes from 142.250.185.206: icmp_seq=1 ttl=115 time=20.3 ms
    // or timeout: Request timeout for icmp_seq N
    lazy_static::lazy_static! {
        static ref TIME_RE: Regex = Regex::new(r"time=(\d+(?:\.\d+)?) ms").unwrap();
        static ref TIMEOUT_RE: Regex = Regex::new(r"(?:Request timeout|no answer yet)").unwrap();
    }

    if let Some(caps) = TIME_RE.captures(line) {
        let ms: f64 = caps[1].parse().unwrap_or(0.0);
        let duration = Duration::from_micros((ms * 1000.0) as u64);
        return PingResult::Pong(duration, line.to_string());
    }

    if TIMEOUT_RE.is_match(line) {
        return PingResult::Timeout(line.to_string());
    }

    PingResult::Unknown(line.to_string())
}

pub fn create_ping(
    target: &str,
    ipv4: bool,
    ipv6: bool,
    interface: Option<&str>,
    extra_args: &[String],
) -> Result<Box<dyn Iterator<Item = PingResult> + Send>, PingError> {
    let mut cmd = if ipv6 {
        Command::new("ping6")
    } else {
        Command::new("ping")
    };

    if ipv4 && !ipv6 {
        cmd.arg("-4");
    }

    if let Some(iface) = interface {
        cmd.arg("-I").arg(iface);
    }

    cmd.args(extra_args);
    cmd.arg(target);

    cmd.stdout(Stdio::piped());
    cmd.stderr(Stdio::null());

    let mut child = cmd.spawn().map_err(PingError::SpawnError)?;
    let stdout = child.stdout.take().ok_or(PingError::ParseError)?;
    let reader = BufReader::new(stdout);

    use std::io::BufRead;
    let lines = reader.lines();

    Ok(Box::new(PingIter {
        child,
        lines,
        parser: Box::new(parse_ping_line),
    }))
}
EOF

